<section class="admin-head"><div><p class="eyebrow">CMS editor</p><h1><?=e($item['title']??'New content')?></h1><p>Status: <?=e($item['status']??'DRAFT')?></p></div><a class="btn outline" href="<?=e(url('/admin/cms'))?>">Back to CMS</a></section>
<form method="post" class="admin-card stack"><?=csrf_field()?><div class="admin-grid two"><label>Type<select name="type"><?php foreach(cms_types() as $k=>$v):?><option value="<?=e($k)?>" <?=($item['type']??'')===$k?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></label><label>Slug<input name="slug" value="<?=e($item['slug']??'')?>" placeholder="auto-from-title"></label></div><label>Title<input name="title" value="<?=e($item['title']??'')?>" required></label><label>Excerpt<textarea name="excerpt" rows="3"><?=e($item['excerpt']??'')?></textarea></label><label>Body<textarea name="body" rows="18" placeholder="Plain editorial text. Separate paragraphs with blank lines. Use ## Heading and - list items."><?=e($item['body']??'')?></textarea></label><label>Hero image filename<input name="hero_image" value="<?=e($item['hero_image']??'')?>"></label><div class="admin-grid two"><label>SEO title<input name="seo_title" value="<?=e($item['seo']['title']??'')?>"></label><label>SEO description<textarea name="seo_description" rows="3"><?=e($item['seo']['description']??'')?></textarea></label></div><label><input type="checkbox" name="noindex" value="1" <?=!empty($item['seo']['noindex'])?'checked':''?>> Noindex this content</label><button class="btn primary">Save content</button></form>
<?php if(!empty($item['guid'])):?><section class="admin-card"><h2>Publishing</h2><form method="post" action="<?=e(url('/admin/cms/'.$item['guid'].'/publish'))?>"><?=csrf_field()?><input type="hidden" name="publish" value="<?=($item['status']??'')==='PUBLISHED'?'0':'1'?>"><button class="btn <?=($item['status']??'')==='PUBLISHED'?'outline':'primary'?>"><?=($item['status']??'')==='PUBLISHED'?'Return to draft':'Publish now'?></button></form><?php if(($item['status']??'')==='PUBLISHED'):?><p><a href="<?=e(url(cms_content_route($item)))?>" target="_blank">View published page ↗</a></p><?php endif;?></section><?php endif;?>
